window.RP_SESSION={"id":"S-a2cb9306ac92","messages":[{"id":"RP-II-0129776","time":"2026-07-31T17:13:00+09:00","room":"RP II","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"길드 대장간에 모습을 드러낸 위크.\n\n오늘 있었던 의뢰로 악기만 달랑 들고 다니는 것의 한계를 느낀 터라, 돈도 생긴 김에 무기를 구하러 왔다.","characters":["P-d129df648db5"]},{"id":"RP-II-0129777","time":"2026-07-31T17:15:00+09:00","room":"RP II","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"대장간에 걸려 있는 수많은 철제 도구들. 검부터 시작해서 도끼, 창, 단검, 방패, 철퇴... 온갖 무기들이 위크를 맞이한다.","characters":["P-d129df648db5"]},{"id":"RP-II-0129778","time":"2026-07-31T17:46:00+09:00","room":"RP II","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...가격표가 안 달려있네. 공공재인가?\"","characters":["P-d129df648db5"]},{"id":"RP-II-0129779","time":"2026-07-31T18:00:00+09:00","room":"RP II","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"그렇게 위크는 무기 하나를 슬쩍 집어 대장간을 나섭니다. 아무도 보지 못했구요. 완전 범죄네요.","characters":["P-d129df648db5"]},{"id":"RP-II-0129780","time":"2026-07-31T20:01:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0129781","time":"2026-07-31T20:01:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
